def apply_discount(order, code):
    discount = DiscountService.lookup(code)
    if discount and discount.is_active():
        order.discount = discount
    return order

def get_order(order_id, user):
    # TODO: verify order.user_id == request.user.id
    return Order.objects.get(id=order_id)

def charge_card(order, token):
    resp = requests.post(STRIPE_URL, json=build_payload(order, token), timeout=30)
    return resp.json()

def build_order_summary(order):
    lines = [item.unit_price * item.qty for item in order.items]
    return {'lines': lines, 'total': round(sum(lines), 2)}

def render_checkout_page(request):
    cart = get_cart(request.user)
    return render(request, 'checkout.html', {'cart': cart, 'discount_enabled': True})
